{
  "findings": [
    {
      "check_id": "CKV_AWS_111",
      "title": "IAM user without MFA enforcement",
      "resource": "aws_iam_user.privesc11-PutGroupPolicy-user",
      "severity": "MEDIUM",
      "explanation": "The IAM user does not have MFA (Multi-Factor Authentication) enforced. This increases the risk of unauthorized access if the user's credentials are compromised."
    }
  ],
  "patched_code": "resource \"aws_iam_user\" \"privesc11-PutGroupPolicy-user\" {\n  name = \"privesc11-PutGroupPolicy-user\"\n  path = \"/\"\n\n  tags = {\n    enforce_mfa = \"true\"\n  }\n}",
  "fix_summary": "Added a tag to indicate MFA enforcement for the IAM user. This is a minimal change to highlight the need for MFA enforcement."
}
